import { writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { tailwindAliases } from '../src/tailwindAliases';
import { baseTheme } from '../src/theme';

const { accent, surface, ...roles } = baseTheme.roles;
const theme = { ...baseTheme, roles: { accent, surface, ...roles } };
const header =
	'/* Generated by scripts/generate-tailwind-css.ts. Run bun run build:package to update. */\n';

for (const [file, css] of [
	['tailwind.css', tailwindAliases(theme)],
	[
		'tailwind-inverted.css',
		tailwindAliases({ ...theme, tokens: [] }, { inverted: true }),
	],
]) {
	const formatted = css
		.split('\n')
		.map((line) =>
			line.length > 79
				? line.replace(/var\((.+)\);$/, 'var(\n\t\t$1\n\t);')
				: line,
		)
		.join('\n');
	writeFileSync(join(import.meta.dirname, '..', file), header + formatted);
}
